<?php
namespace App\Filament\Resources;
use App\Filament\Resources\LocationResource\Pages; use App\Models\Location; use App\Services\TaxonomyValueClassifier; use Filament\Actions\{DeleteAction,EditAction}; use Filament\Forms\Components\{Select,TextInput}; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\TernaryFilter; use Filament\Tables\Table; use Illuminate\Database\Eloquent\Builder;
class LocationResource extends TaxonomyResource {protected static ?string $model=Location::class;protected static string|null|\BackedEnum $navigationIcon='heroicon-o-map-pin';protected static ?string $navigationLabel='Géographie';
 public static function form(Schema $schema):Schema{return $schema->components([TextInput::make('name')->required()->maxLength(255)->rule(function(){return function(string $attribute,mixed $value,\Closure $fail):void{if(app(TaxonomyValueClassifier::class)->isMalicious((string)$value))$fail('Cette valeur ressemble à une charge technique et ne peut pas être un lieu.');};}),TextInput::make('slug')->required()->alphaDash()->unique(ignoreRecord:true),Select::make('parent_id')->label('Parent')->relationship('parent','name')->searchable()->preload()]);}
 public static function table(Table $table):Table{return $table->columns([TextColumn::make('name')->label('Lieu')->searchable()->sortable(),TextColumn::make('slug')->searchable()->sortable(),TextColumn::make('parent.name')->label('Parent')->placeholder('Racine')->toggleable(),TextColumn::make('level')->label('Niveau')->state(fn(Location $location)=>$location->parent_id?'Sous-zone':'Zone racine'),TextColumn::make('restaurants_count')->label('Restaurants')->counts('restaurants')->sortable(),TextColumn::make('updated_at')->label('Modifié')->dateTime('d/m/Y H:i')->sortable()])->filters([TernaryFilter::make('without_restaurants')->label('Sans restaurant')->queries(true:fn(Builder $query)=>$query->doesntHave('restaurants'),false:fn(Builder $query)=>$query->has('restaurants'))])->recordActions([EditAction::make(),DeleteAction::make()->requiresConfirmation()->visible(fn(Location $location)=>!$location->restaurants()->exists())])->defaultSort('name');}
 public static function getPages():array{return ['index'=>Pages\ListLocations::route('/')];}}
